/**
 * Chart containers of the organisation reports dashboard (Chart.js from core).
 *
 * Every chart is validated before drawing. Values handed to Chart.js are plain numbers and the options hold no
 * functions other than documented callbacks: Chart.js resolves any other function in its options as a "scriptable
 * option" and calls it with its own context object, which is what made formatting fail with "Cannot convert object to
 * primitive value".
 *
 * @module     report_orgreports/chart_panel
 * @copyright  2026
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('report_orgreports/chart_panel', ['core/chartjs', 'report_orgreports/format'], function(Chart, F) {
    'use strict';

    /** Sky and blue first, then restrained supporting hues. */
    var PALETTE = ['#0ea5e9', '#2563eb', '#7dd3fc', '#6366f1', '#14b8a6', '#93c5fd', '#f59e0b', '#a5b4fc', '#94a3b8',
        '#0e7490'];
    var STATUS = ['#22c55e', '#f59e0b', '#94a3b8', '#ef4444'];
    var TYPES = ['line', 'area', 'bar', 'stacked', 'hbar', 'doughnut'];
    var HEIGHTS = {wide: 300, narrow: 300, half: 260, full: 280};

    /**
     * Check and normalise a chart from the server; throws when it cannot be drawn.
     *
     * @param {Object} spec
     * @returns {Object}
     */
    var validate = function(spec) {
        if (!spec || typeof spec !== 'object') {
            throw new Error('chart is not an object');
        }
        if (TYPES.indexOf(spec.type) === -1) {
            throw new Error('unknown chart type ' + spec.type);
        }
        if (!Array.isArray(spec.labels) || !Array.isArray(spec.datasets)) {
            throw new Error('chart ' + spec.key + ' has no labels or datasets');
        }
        var labels = spec.labels.map(function(l) {
            return F.decode(l);
        });
        var datasets = spec.datasets.map(function(d) {
            var data = Array.isArray(d && d.data) ? d.data.map(F.toNumber) : [];
            // Each dataset has one value per label.
            while (data.length < labels.length) {
                data.push(0);
            }
            return {label: F.decode(d && d.label), data: data.slice(0, labels.length)};
        });
        var empty = !labels.length || datasets.every(function(d) {
            return d.data.every(function(v) {
                return v === 0;
            });
        });
        return {key: String(spec.key || ''), title: String(spec.title || ''), type: spec.type, labels: labels,
            datasets: datasets, unit: String(spec.unit || 'count'), summary: spec.summary || '',
            size: HEIGHTS[spec.size] ? spec.size : 'half', empty: empty || !!spec.empty};
    };

    /**
     * Plugin writing the total in the middle of a doughnut. The formatter is closed over, not put in the options.
     *
     * @param {Function} format
     * @returns {Object}
     */
    var centreTotal = function(format) {
        return {
            id: 'orgrCentreTotal',
            afterDraw: function(chart) {
                var meta = chart.getDatasetMeta(0);
                if (!meta || !meta.data || !meta.data[0]) {
                    return;
                }
                var total = (chart.data.datasets[0].data || []).reduce(function(a, b) {
                    return a + F.toNumber(b);
                }, 0);
                var ctx = chart.ctx;
                var family = Chart.defaults.font.family;
                ctx.save();
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillStyle = '#0f172a';
                ctx.font = '700 18px ' + family;
                ctx.fillText(format(total), meta.data[0].x, meta.data[0].y - 8);
                ctx.fillStyle = '#64748b';
                ctx.font = '500 11px ' + family;
                ctx.fillText(F.str('total'), meta.data[0].x, meta.data[0].y + 11);
                ctx.restore();
            }
        };
    };

    /**
     * Chart.js configuration for a validated chart.
     *
     * @param {Object} spec
     * @param {CanvasRenderingContext2D|null} context2d
     * @returns {Object}
     */
    var configure = function(spec, context2d) {
        var format = F.formatter(spec.unit, false);
        var axisFormat = F.formatter(spec.unit, true);
        var type = spec.type;
        var doughnut = type === 'doughnut';
        var horizontal = type === 'hbar';
        var stacked = type === 'stacked';
        var line = type === 'line' || type === 'area';

        var datasets = spec.datasets.map(function(d, i) {
            var colour = PALETTE[i % PALETTE.length];
            var set = {label: d.label, data: d.data, borderColor: colour, backgroundColor: colour};
            if (doughnut) {
                set.backgroundColor = spec.labels.map(function(l, j) {
                    return spec.key === 'statusdistribution' ? STATUS[j % STATUS.length] : PALETTE[j % PALETTE.length];
                });
                set.borderColor = '#ffffff';
                set.borderWidth = 2;
                set.hoverOffset = 4;
            } else if (line) {
                set.tension = 0.3;
                set.borderWidth = 2;
                set.pointRadius = spec.labels.length > 31 ? 0 : 2.5;
                set.pointHoverRadius = 4;
                set.pointBackgroundColor = '#ffffff';
                set.fill = type === 'area' ? 'origin' : false;
                set.backgroundColor = colour + '1f';
                if (type === 'area' && context2d && context2d.createLinearGradient) {
                    var gradient = context2d.createLinearGradient(0, 0, 0, HEIGHTS[spec.size]);
                    gradient.addColorStop(0, colour + '33');
                    gradient.addColorStop(1, colour + '00');
                    set.backgroundColor = gradient;
                }
            } else {
                var fill = spec.key === 'attempts' ? STATUS[i % STATUS.length] : colour;
                set.backgroundColor = fill;
                set.borderColor = fill;
                set.borderRadius = stacked ? 2 : 5;
                set.borderSkipped = false;
                set.maxBarThickness = horizontal ? 20 : 26;
            }
            return set;
        });

        var options = {
            responsive: true,
            maintainAspectRatio: false,
            animation: {duration: 400},
            interaction: {mode: doughnut ? 'nearest' : 'index', intersect: doughnut},
            plugins: {
                legend: {
                    display: doughnut || datasets.length > 1,
                    position: doughnut ? 'bottom' : 'top',
                    align: doughnut ? 'center' : 'end',
                    labels: {usePointStyle: true, pointStyle: 'circle', boxWidth: 8, boxHeight: 8, padding: 12,
                        color: '#334155', font: {size: 12}}
                },
                tooltip: {
                    backgroundColor: '#ffffff', titleColor: '#0f172a', bodyColor: '#334155', borderColor: '#dbe4ee',
                    borderWidth: 1, padding: 10, cornerRadius: 8, boxPadding: 4, usePointStyle: true,
                    callbacks: {
                        label: function(item) {
                            if (doughnut) {
                                var total = item.dataset.data.reduce(function(a, b) {
                                    return a + F.toNumber(b);
                                }, 0);
                                var value = F.toNumber(item.raw);
                                return ' ' + (spec.labels[item.dataIndex] || '') + ': ' + format(value) +
                                    (total ? ' (' + Math.round(value / total * 100) + '%)' : '');
                            }
                            return ' ' + item.dataset.label + ': ' + format(F.toNumber(item.raw));
                        }
                    }
                }
            }
        };
        if (doughnut) {
            options.cutout = '68%';
        } else {
            var valueAxis = {beginAtZero: true, stacked: stacked, border: {display: false},
                grid: {color: '#eef2f7', drawTicks: false},
                ticks: {color: '#94a3b8', padding: 8, maxTicksLimit: 6, callback: function(value) {
                    return axisFormat(F.toNumber(value));
                }}};
            if (spec.unit === 'count') {
                valueAxis.ticks.precision = 0;
            }
            var labels = spec.labels;
            var labelAxis = {stacked: stacked, border: {display: false}, grid: {display: false},
                ticks: {color: '#94a3b8', autoSkip: true, maxRotation: 0, autoSkipPadding: 14, callback: function(value,
                        index) {
                    var label = labels[typeof value === 'number' ? value : index];
                    label = label === undefined ? String(value) : label;
                    return label.length > 24 ? label.substr(0, 22) + '…' : label;
                }}};
            options.scales = horizontal ? {x: valueAxis, y: labelAxis} : {x: labelAxis, y: valueAxis};
            if (horizontal) {
                options.indexAxis = 'y';
            }
        }
        return {
            type: doughnut ? 'doughnut' : (line ? 'line' : 'bar'),
            data: {labels: spec.labels, datasets: datasets},
            options: options,
            plugins: doughnut ? [centreTotal(format)] : []
        };
    };

    var instances = [];

    return {
        validate: validate,
        configure: configure,

        /**
         * Destroy the charts drawn before.
         */
        destroyAll: function() {
            instances.forEach(function(chart) {
                try {
                    chart.destroy();
                } catch (e) {
                    F.logError('chart destroy', e);
                }
            });
            instances = [];
        },

        /**
         * Draw a section's charts into a grid; a chart that cannot be drawn shows its own error state.
         *
         * @param {HTMLElement} grid
         * @param {Array} specs
         */
        render: function(grid, specs) {
            Chart.defaults.font.family = window.getComputedStyle(document.body).fontFamily;
            Chart.defaults.color = '#64748b';
            (specs || []).forEach(function(raw) {
                var panel = document.createElement('section');
                var spec;
                try {
                    spec = validate(raw);
                } catch (e) {
                    F.logError('invalid chart data', e);
                    spec = {key: '', title: raw && raw.title ? String(raw.title) : '', size: 'half', invalid: true};
                }
                panel.className = 'orgr-panel orgr-chart orgr-size-' + spec.size;
                panel.innerHTML = '<div class="orgr-panel-head"><h3 class="orgr-panel-title">' + F.esc(spec.title) + '</h3>' +
                    (spec.summary ? '<div class="orgr-panel-summary">' + spec.summary + '</div>' : '') + '</div>';
                var holder = document.createElement('div');
                holder.className = 'orgr-chart-holder';
                holder.style.height = (HEIGHTS[spec.size] || 260) + 'px';
                panel.appendChild(holder);
                grid.appendChild(panel);
                if (spec.invalid) {
                    holder.classList.add('orgr-empty');
                    holder.innerHTML = '<span class="orgr-empty-icon orgr-empty-icon-error" aria-hidden="true">' +
                        '<i class="fa-solid fa-triangle-exclamation"></i></span><strong>' + F.esc(F.str('chartfailed')) +
                        '</strong>';
                    return;
                }
                if (spec.empty) {
                    holder.classList.add('orgr-empty');
                    holder.innerHTML = '<span class="orgr-empty-icon" aria-hidden="true"><i class="fa-solid fa-chart-column">' +
                        '</i></span><strong>' + F.esc(F.str('nochartdata')) + '</strong><span>' +
                        F.esc(F.str('customneeded')) + '</span>';
                    return;
                }
                var canvas = document.createElement('canvas');
                canvas.setAttribute('role', 'img');
                canvas.setAttribute('aria-label', spec.title + (spec.summary ? ' – ' + F.decode(spec.summary) : ''));
                holder.appendChild(canvas);
                try {
                    instances.push(new Chart(canvas, configure(spec, canvas.getContext ? canvas.getContext('2d') : null)));
                } catch (e) {
                    F.logError('chart ' + spec.key + ' failed', e);
                    holder.classList.add('orgr-empty');
                    holder.innerHTML = '<span class="orgr-empty-icon orgr-empty-icon-error" aria-hidden="true">' +
                        '<i class="fa-solid fa-triangle-exclamation"></i></span><strong>' + F.esc(F.str('chartfailed')) +
                        '</strong>';
                }
            });
        }
    };
});
